import asyncio
import datetime
import decimal
import json
import math
import re
import uuid
from urllib.parse import parse_qs, quote, unquote, urlparse

import perceivo

_OPERATIONS = ("SELECT", "INSERT", "UPDATE", "DELETE", "CUSTOM")
_MODES = ("platform", "external")
_DB_TYPES = ("postgresql", "mssql", "sqlite", "bigquery")

# A CUSTOM statement starting with one of these only reads; any other CUSTOM
# statement is sent as a write, which needs the write privilege in platform mode.
_READ_KEYWORDS = ("SELECT", "WITH", "SHOW", "EXPLAIN", "VALUES", "TABLE")

# The platform caps a query at 10000 rows; the same ceiling applies everywhere.
_MAX_ROWS_CAP = 10000

# ${field} placeholders are resolved from request_data. The author-quoted form
# ('${field}') is one placeholder, so a string is never quoted twice.
_QUOTED_PARAM = re.compile(r"'\$\{(\w+)\}'")
_PARAM = re.compile(r"\$\{(\w+)\}")
# A PostgreSQL dollar-quoted string opens with $$ or $tag$ and closes with the same.
# A tag may hold any non-ASCII character, as a PostgreSQL identifier may.
_DOLLAR_TAG = re.compile(r"\$(?:[A-Za-z_\u0080-\U0010ffff][A-Za-z0-9_\u0080-\U0010ffff]*)?\$")


def _word_char(template: str, i: int) -> bool:
    """Whether template[i] exists and could continue an identifier or keyword."""
    if not 0 <= i < len(template):
        return False
    char = template[i]
    return char.isalnum() or char in "_$" or ord(char) > 0x7F


def _continues(template: str, j: int) -> int:
    """Where a PostgreSQL string closed just before j continues, or -1.

    PostgreSQL joins two string constants separated only by whitespace that holds a
    newline (a -- comment counts as whitespace), and the second keeps the first's
    escape rules: E'a'<newline>'\\'' is one backslash-escaped string.
    """
    n = len(template)
    newline = False
    while j < n:
        if template[j] in "\r\n":
            newline = True
            j += 1
        elif template[j] in " \t\f\v":
            j += 1
        elif template.startswith("--", j):
            j = _line_end(template, j, "postgresql")
        else:
            break
    return j if newline and template[j : j + 1] == "'" else -1


def _line_end(template: str, i: int, db_type: str) -> int:
    """Where the line comment starting at i ends.

    PostgreSQL ends one at a CR or an LF. The others end it at an LF, and a lone CR
    inside it is refused: an engine that reads that CR as a line end would see the
    rest of the line as SQL, where a quote could hide.
    """
    n = len(template)
    lf = template.find("\n", i)
    lf = n if lf < 0 else lf
    cr = template.find("\r", i, lf)
    if cr < 0:
        return lf
    if db_type == "postgresql":
        return cr
    if cr != lf - 1:
        raise ValueError(
            "The statement has a carriage return inside a comment with no line feed after "
            "it. Use LF or CRLF line endings."
        )
    return lf


def _param(name: str, default: str = "") -> str:
    value = perceivo.params.get(name, default)
    return str(default if value is None else value).strip()


def _choice(name: str, default: str, options: tuple, label: str, upper: bool = False) -> str:
    value = _param(name, default) or default
    value = value.upper() if upper else value.lower()
    if value not in options:
        raise ValueError(f"{label} is {value!r}. Choose one of: {', '.join(options)}.")
    return value


def _max_rows() -> int:
    """Max Rows as a whole number of at least 1, capped at the platform ceiling."""
    raw = perceivo.params.get("max_rows", 100)
    if raw is None or str(raw).strip() == "":
        return 100
    if isinstance(raw, float) and raw.is_integer():
        raw = int(raw)
    try:
        if isinstance(raw, bool):
            raise ValueError
        value = int(str(raw).strip())
    except ValueError:
        raise ValueError(f"Max Rows must be a whole number, not {raw!r}.") from None
    if value < 1:
        raise ValueError("Max Rows must be at least 1.")
    return min(value, _MAX_ROWS_CAP)


def _literal(value, db_type: str) -> str:
    """Render one request_data value as a quoted SQL literal for db_type."""
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        if db_type == "mssql":
            return "1" if value else "0"
        return "TRUE" if value else "FALSE"
    if isinstance(value, (int, float)):
        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError("A placeholder value is not a finite number.")
        return repr(value)
    if isinstance(value, (dict, list)):
        value = json.dumps(value)
    text = str(value)
    if db_type == "bigquery":
        # BigQuery escapes with backslashes and refuses a raw newline in a string.
        escaped = (
            text.replace("\\", "\\\\").replace("'", "\\'").replace("\n", "\\n").replace("\r", "\\r")
        )
        return "'" + escaped + "'"
    if db_type == "postgresql":
        # An escape string reads the same whatever precedes it and whatever
        # standard_conforming_strings says: a value can never be read in another mode.
        return "E'" + text.replace("\\", "\\\\").replace("'", "''") + "'"
    quoted = "'" + text.replace("'", "''") + "'"
    return "N" + quoted if db_type == "mssql" else quoted


def _region_end(template: str, i: int, db_type: str):
    """Where the comment, string or quoted name starting at i ends, and what it is.

    Returns (end, kind), or (i, None) when nothing of the kind starts at i. An
    unterminated region runs to the end of the statement.
    """
    n = len(template)
    pair = template[i : i + 2]
    if pair == "--" or (template[i] == "#" and db_type == "bigquery"):
        return _line_end(template, i, db_type), "a comment"
    if pair == "/*":
        # PostgreSQL and SQL Server nest block comments; the others end at the first */.
        nests = db_type in ("postgresql", "mssql")
        depth = 0
        j = i
        while j < n:
            if template.startswith("/*", j) and (nests or depth == 0):
                depth += 1
                j += 2
            elif template.startswith("*/", j):
                depth -= 1
                j += 2
                if depth == 0:
                    return j, "a comment"
            else:
                j += 1
        return n, "a comment"
    char = template[i]
    if char == "'" or (char == '"' and db_type == "bigquery"):
        if db_type == "bigquery":
            # BigQuery escapes only with a backslash, and three quotes open a
            # triple-quoted string that only three quotes close.
            close = char * 3 if template.startswith(char * 3, i) else char
            j = i + len(close)
            while j < n:
                if template[j] == "\\":
                    j += 2
                elif template.startswith(close, j):
                    return j + len(close), "a quoted string"
                else:
                    j += 1
            return n, "a quoted string"
        # A PostgreSQL E'...' string also escapes with a backslash.
        backslash = (
            db_type == "postgresql"
            and i > 0
            and template[i - 1] in "eE"
            and not _word_char(template, i - 2)
        )
        j = i + 1
        while j < n:
            if backslash and template[j] == "\\":
                j += 2
                continue
            if template[j] == char:
                if template[j + 1 : j + 2] == char:
                    j += 2
                    continue
                if char == "'" and db_type == "postgresql":
                    more = _continues(template, j + 1)
                    if more >= 0:
                        j = more + 1
                        continue
                return j + 1, "a quoted string"
            j += 1
        return n, "a quoted string"
    if char == '"' or char == "`" or (char == "[" and db_type in ("mssql", "sqlite")):
        close = "]" if char == "[" else char
        # A BigQuery quoted name escapes with a backslash, as its strings do.
        backslash = char == "`" and db_type == "bigquery"
        j = i + 1
        while j < n:
            if backslash and template[j] == "\\":
                j += 2
                continue
            if template[j] == close:
                if backslash:
                    return j + 1, "a quoted name"
                if template[j + 1 : j + 2] == close:
                    j += 2
                    continue
                return j + 1, "a quoted name"
            j += 1
        return n, "a quoted name"
    # In a name such as a$b$ the $b$ is part of the name, not a dollar quote.
    dollar = db_type == "postgresql" and not _word_char(template, i - 1)
    tag = _DOLLAR_TAG.match(template, i) if dollar else None
    if tag:
        end = template.find(tag.group(0), tag.end())
        return (n if end < 0 else end + len(tag.group(0))), "a quoted string"
    return i, None


def _resolve(template: str, request_data: dict, db_type: str) -> str:
    """Replace every ${field} with request_data[field] as a quoted literal.

    A field the statement names but request_data lacks is a configuration error,
    never a silent NULL: `SET status = ${status}` must not blank a column.

    A placeholder may stand only where a value goes. Inside a string the author
    quoted, such as '%${q}%', its value would land inside that string, where one
    quote ends the string and the rest runs as SQL, so it is refused. Build the
    string by concatenation instead: '%' || ${q} || '%' (CONCAT('%', ${q}, '%') on
    SQL Server and BigQuery). The statement is read the way the database reads it:
    a quote inside a comment or a quoted name opens no string, and a placeholder
    inside a comment or a quoted name is refused too, because a value with a
    newline would end the comment, and a value cannot name a table or column. A
    placeholder joined to the word before it, such as E'${q}', U&'${q}' or N${q}, is refused,
    because the prefix would change how the database reads the quoted value; so is one
    joined to the quote before it, such as 'a'${q}, which would extend that string. On
    PostgreSQL a value is an escape string, E'...', so it reads the same after any
    string, continued or not. PostgreSQL ends a line at a CR as well as an LF; on the
    other engines a lone CR inside a comment is refused.
    """

    def literal(name: str) -> str:
        if name not in request_data:
            raise ValueError(
                f"The statement uses the placeholder for {name!r} but request_data has no "
                f"field {name!r}."
            )
        return _literal(request_data[name], db_type)

    out = []
    i = 0
    while i < len(template):
        placeholder = _QUOTED_PARAM.match(template, i) or _PARAM.match(template, i)
        if placeholder:
            if _word_char(template, i - 1) or template[max(i - 2, 0) : i].lower() == "u&":
                raise ValueError(
                    f"The placeholder for {placeholder.group(1)!r} is joined to the word "
                    "before it. Put a space or an operator between them."
                )
            if i > 0 and template[i - 1] in "'\"`]":
                raise ValueError(
                    f"The placeholder for {placeholder.group(1)!r} is joined to the quote "
                    "before it. Put a space or an operator between them."
                )
            out.append(literal(placeholder.group(1)))
            i = placeholder.end()
            continue
        end, kind = _region_end(template, i, db_type)
        if kind:
            inside = _PARAM.search(template, i, end)
            if inside:
                name = inside.group(1)
                if kind == "a quoted string":
                    hint = f"Concatenate it instead, for example '%' || ${{{name}}} || '%'."
                elif kind == "a comment":
                    hint = "Move it out of the comment."
                else:
                    hint = "A value cannot name a table or column."
                raise ValueError(f"The placeholder for {name!r} is inside {kind}. {hint}")
            out.append(template[i:end])
            i = end
            continue
        out.append(template[i])
        i += 1
    return "".join(out)


def _table(db_type: str) -> str:
    table = _param("table_name")
    if not table:
        raise ValueError("Table Name is required for SELECT, INSERT, UPDATE and DELETE.")
    schema = _param("schema_name", "public")
    # "public" is PostgreSQL's default schema; elsewhere it is treated as unset.
    if schema == "public" and db_type in ("mssql", "sqlite"):
        schema = ""
    return f"{schema}.{table}" if schema else table


def _where(request_data: dict, db_type: str) -> str:
    where = _param("where_clause")
    return f" WHERE {_resolve(where, request_data, db_type)}" if where else ""


def _build_query(operation: str, request_data: dict, db_type: str, fetch: int) -> str:
    """The statement for operation. A SELECT asks for fetch rows (Max Rows + 1)."""
    if operation == "CUSTOM":
        raw = _param("custom_query")
        if not raw:
            raise ValueError("Operation is CUSTOM but Custom SQL is empty.")
        return _resolve(raw, request_data, db_type)

    table = _table(db_type)

    if operation == "SELECT":
        columns = _param("columns", "*") or "*"
        sql_tail = f" FROM {table}{_where(request_data, db_type)}"
        group_by = _param("group_by")
        if group_by:
            sql_tail += f" GROUP BY {group_by}"
        order_by = _param("order_by")
        if order_by:
            sql_tail += f" ORDER BY {order_by}"
        if db_type == "mssql":
            distinct = ""
            if columns[:9].upper() == "DISTINCT ":
                distinct, columns = "DISTINCT ", columns[9:].lstrip()
            return f"SELECT {distinct}TOP {fetch} {columns}{sql_tail}"
        return f"SELECT {columns}{sql_tail} LIMIT {fetch}"

    if operation == "INSERT":
        insert_columns = _param("insert_columns")
        insert_values = _param("insert_values")
        if not insert_columns or not insert_values:
            raise ValueError("INSERT needs both Insert Columns and Insert Values.")
        values_sql = _resolve(insert_values, request_data, db_type)
        return f"INSERT INTO {table} ({insert_columns}) VALUES ({values_sql})"

    if operation == "UPDATE":
        set_clause = _param("set_clause")
        if not set_clause:
            raise ValueError("UPDATE needs a SET Clause.")
        set_sql = _resolve(set_clause, request_data, db_type)
        return f"UPDATE {table} SET {set_sql}{_where(request_data, db_type)}"

    return f"DELETE FROM {table}{_where(request_data, db_type)}"


def _json_safe(value):
    """A driver value as JSON, the same way the platform serializes its rows."""
    if value is None or isinstance(value, (bool, int, str)):
        return value
    if isinstance(value, float):
        return value if math.isfinite(value) else str(value)
    if isinstance(value, decimal.Decimal):
        return float(value)
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return value.isoformat()
    if isinstance(value, uuid.UUID):
        return str(value)
    if isinstance(value, (bytes, bytearray, memoryview)):
        return f"(binary, {len(bytes(value))} bytes)"
    if isinstance(value, dict):
        return {str(key): _json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(item) for item in value]
    return str(value)


def _rows(columns: list, records, max_rows: int) -> dict:
    """Key each record by column, cap it at max_rows and say whether it was cut."""
    records = list(records)
    truncated = len(records) > max_rows
    rows = [
        {column: _json_safe(value) for column, value in zip(columns, record, strict=True)}
        for record in records[:max_rows]
    ]
    return {"columns": columns, "rows": rows, "row_count": len(rows), "truncated": truncated}


def _affected(count, truncated: bool = False) -> dict:
    count = count if isinstance(count, int) and count >= 0 else 0
    return {"columns": [], "rows": [], "row_count": count, "truncated": truncated}


def _connect_failed(db_type: str, exc: Exception) -> ConnectionError:
    # The driver's message can echo the connection string, so only its type is kept.
    return ConnectionError(
        f"Could not connect to the external {db_type} database ({type(exc).__name__}). "
        "Check the connection_string secret and that the host has an outbound route."
    )


def _mssql_dsn(connection_string: str) -> str:
    """mssql://user:password@host:port/database[?TrustServerCertificate=yes] as an ODBC DSN."""
    parsed = urlparse(connection_string)
    database = parsed.path.lstrip("/")
    if not parsed.hostname or not database or parsed.username is None:
        raise ValueError(
            "The connection_string secret for mssql must look like "
            "mssql://user:password@host:1433/database."
        )

    def braced(value) -> str:
        return "{" + str(value).replace("}", "}}") + "}"

    options = parse_qs(parsed.query)
    trust = (options.get("TrustServerCertificate") or ["no"])[0].lower() in ("yes", "true", "1")
    parts = [
        "DRIVER={ODBC Driver 18 for SQL Server}",
        f"SERVER={braced(f'{parsed.hostname},{parsed.port or 1433}')}",
        f"DATABASE={braced(unquote(database))}",
        f"UID={braced(unquote(parsed.username))}",
        f"PWD={braced(unquote(parsed.password or ''))}",
        "Encrypt=yes",
        f"TrustServerCertificate={'yes' if trust else 'no'}",
    ]
    return ";".join(parts) + ";"


def _sqlite_uri(connection_string: str) -> str:
    path = connection_string
    for prefix in ("sqlite:///", "sqlite://"):
        if path.startswith(prefix):
            path = path[len(prefix) :]
            break
    if not path:
        raise ValueError("The connection_string secret for sqlite must name a database file.")
    # mode=rw: a missing file is an error, never a new empty database.
    return "file:" + quote(path.replace("\\", "/"), safe="/:") + "?mode=rw"


def _bigquery_credentials(connection_string: str) -> dict:
    try:
        info = json.loads(connection_string)
    except ValueError:
        info = None
    if not isinstance(info, dict) or not info.get("client_email") or not info.get("project_id"):
        raise ValueError(
            "The connection_string secret for bigquery must be a service-account JSON key "
            "with client_email and project_id."
        )
    return info


async def _run_postgresql(connection_string: str, sql: str, read: bool, max_rows: int) -> dict:
    import asyncpg

    try:
        connection = await asyncpg.connect(connection_string)
    except Exception as exc:
        raise _connect_failed("postgresql", exc) from None
    try:
        if read:
            statement = await connection.prepare(sql)
            columns = [attribute.name for attribute in statement.get_attributes()]
            records = await statement.fetch()
            return _rows(columns, [tuple(record.values()) for record in records], max_rows)
        status = await connection.execute(sql)
        tail = str(status or "").rsplit(" ", 1)[-1]
        return _affected(int(tail) if tail.isdigit() else 0)
    finally:
        await connection.close()


async def _run_sqlite(uri: str, sql: str, read: bool, max_rows: int) -> dict:
    import aiosqlite

    try:
        connection = await aiosqlite.connect(uri, uri=True)
    except Exception as exc:
        raise _connect_failed("sqlite", exc) from None
    try:
        cursor = await connection.execute(sql)
        if read:
            columns = [item[0] for item in cursor.description or ()]
            records = await cursor.fetchmany(max_rows + 1) if columns else []
            await connection.commit()
            return _rows(columns, records, max_rows)
        await connection.commit()
        return _affected(cursor.rowcount)
    finally:
        await connection.close()


async def _run_mssql(dsn: str, sql: str, read: bool, max_rows: int) -> dict:
    import aioodbc

    try:
        connection = await aioodbc.connect(dsn=dsn)
    except Exception as exc:
        raise _connect_failed("mssql", exc) from None
    try:
        cursor = await connection.cursor()
        try:
            await cursor.execute(sql)
            if read:
                columns = [item[0] for item in cursor.description or ()]
                records = await cursor.fetchmany(max_rows + 1) if columns else []
                await connection.commit()
                return _rows(columns, records, max_rows)
            await connection.commit()
            return _affected(cursor.rowcount)
        finally:
            await cursor.close()
    finally:
        await connection.close()


def _run_bigquery(info: dict, sql: str, read: bool, max_rows: int) -> dict:
    """Blocking: the BigQuery client is synchronous, so this runs in a worker thread."""
    from google.cloud import bigquery
    from google.oauth2 import service_account

    try:
        credentials = service_account.Credentials.from_service_account_info(info)
        client = bigquery.Client(credentials=credentials, project=info["project_id"])
    except Exception as exc:
        raise _connect_failed("bigquery", exc) from None
    try:
        job = client.query(sql)
        if read:
            result = job.result(max_results=max_rows + 1)
            columns = [field.name for field in result.schema]
            return _rows(columns, [tuple(row.values()) for row in result], max_rows)
        job.result()
        return _affected(job.num_dml_affected_rows)
    finally:
        client.close()


async def _run_external(db_type: str, target, sql: str, read: bool, max_rows: int) -> dict:
    if db_type == "postgresql":
        return await _run_postgresql(target, sql, read, max_rows)
    if db_type == "sqlite":
        return await _run_sqlite(target, sql, read, max_rows)
    if db_type == "mssql":
        return await _run_mssql(target, sql, read, max_rows)
    return await asyncio.to_thread(_run_bigquery, target, sql, read, max_rows)


async def _run_platform(
    database_id: str, sql: str, read: bool, read_only: bool, max_rows: int
) -> dict:
    # The platform answers a write with the rows it returns, not a status line,
    # so RETURNING 1 is what makes the affected-row count real. The newline ends
    # any trailing -- comment in a configured clause. A write past the row cap
    # reports truncated, so its row_count is a floor rather than the total.
    statement = sql if read else sql + "\nRETURNING 1"
    limit = max_rows if read else _MAX_ROWS_CAP
    db = await perceivo.managed_service.database.connect(database_id)
    result = await db.query(statement, read_only=read_only and read, max_rows=limit)
    truncated = bool(result.get("truncated"))
    if not read:
        return _affected(len(result.get("rows") or []), truncated)
    columns = list(result.get("columns") or [])
    rows = [
        dict(zip(columns, row, strict=True)) if isinstance(row, (list, tuple)) else row
        for row in result.get("rows") or []
    ]
    return {"columns": columns, "rows": rows, "row_count": len(rows), "truncated": truncated}


def _error(operation: str, message: str, error_type: str) -> "perceivo.primitives.AgentOutput":
    """A refusal the flow can branch on: the database answered, but said no.

    The payload variable is named uniquely so the contract validator can see
    this literal's fields; reusing one name across payloads hides them.
    """
    perceivo.log.warning(f"Database Connector: {operation} refused ({error_type})")
    error_payload = {
        "success": False,
        "operation": operation,
        "error": message,
        "error_type": error_type,
    }
    return perceivo.primitives.AgentOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data=error_payload,
            mime_type="application/json",
        ),
        response_data=error_payload,
    )


@perceivo.agent
async def database_connector(
    input: perceivo.primitives.AgentInput,
) -> perceivo.primitives.AgentOutput:
    """Run one SQL statement against a platform-provisioned or an external database.

    The statement is built from the node parameters (or is the Custom SQL), with
    ${field} placeholders resolved from request_data as quoted literals. Platform
    mode queries a database the platform provisioned, through the platform;
    external mode connects with the connection_string secret, read by NAME.

    Every setting is checked before anything is sent, and a bad one raises
    ValueError. A platform refusal -- no privilege (403) or the database is not
    running (409) -- is returned as a result with success false. Any other
    failure raises and fails the run. Neither the SQL nor any row is logged.
    """
    request_data = input.request_data or {}
    if not isinstance(request_data, dict):
        raise ValueError("request_data must be an object.")

    operation = _choice("operation", "SELECT", _OPERATIONS, "Operation", upper=True)
    mode = _choice("connection_mode", "platform", _MODES, "Connection Mode")
    db_type = "postgresql"
    if mode == "external":
        db_type = _choice("db_type", "postgresql", _DB_TYPES, "Database Type")
    max_rows = _max_rows()

    sql = _build_query(operation, request_data, db_type, max_rows + 1)
    # read: the result is rows (SELECT, CUSTOM), not an affected-row count.
    # read_only: whether the platform may refuse a write; CUSTOM goes by its verb.
    read = operation in ("SELECT", "CUSTOM")
    read_only = operation == "SELECT"
    if operation == "CUSTOM":
        first_word = (sql.lstrip("( \t\r\n").split(None, 1) or [""])[0].upper()
        read_only = first_word in _READ_KEYWORDS

    if mode == "platform":
        target = _param("platform_database_id")
        if not target:
            raise ValueError("Connection Mode is platform but no Database ID is set.")
    else:
        connection_string = await perceivo.secrets.get("connection_string")
        if not connection_string:
            raise ValueError(
                "Connection Mode is external but no connection_string secret is bound. "
                "Bind one on the orchestration node."
            )
        if db_type == "mssql":
            target = _mssql_dsn(connection_string)
        elif db_type == "sqlite":
            target = _sqlite_uri(connection_string)
        elif db_type == "bigquery":
            target = _bigquery_credentials(connection_string)
        else:
            target = connection_string

    perceivo.log.info(
        f"Database Connector: {operation} ({mode} {db_type})",
        operation=operation,
        connection_mode=mode,
        db_type=db_type,
        read_only=read_only,
    )

    if mode == "platform":
        try:
            result = await _run_platform(target, sql, read, read_only, max_rows)
        except Exception as exc:
            status = getattr(getattr(exc, "response", None), "status_code", None)
            if status == 403:
                return _error(
                    operation,
                    "Access denied: you lack the database privilege this operation needs.",
                    "PermissionError",
                )
            if status == 409:
                return _error(
                    operation,
                    "The database is not running. Start it from the Infrastructure tab.",
                    "ServiceUnavailable",
                )
            raise
    else:
        result = await _run_external(db_type, target, sql, read, max_rows)

    perceivo.log.info(
        f"Database Connector: {operation} completed",
        row_count=result["row_count"],
        truncated=result["truncated"],
    )

    # Each exit builds its own literal payload so every field this agent can
    # return is statically visible to the contract validator.
    if read:
        response_field = _param("response_field_name")
        if response_field:
            # The rows under the configured key, merged into what arrived, so
            # they flow on through a Sequential Executor chain.
            wrapped_payload = {**request_data, response_field: result["rows"]}
            return perceivo.primitives.AgentOutput(
                artifact=perceivo.primitives.Artifact(
                    type=perceivo.primitives.ArtifactType.JSON,
                    data=wrapped_payload,
                    mime_type="application/json",
                ),
                response_data=wrapped_payload,
            )
        read_payload = {
            "success": True,
            "operation": operation,
            "rows": result["rows"],
            "row_count": result["row_count"],
            "columns": result["columns"],
            "truncated": result["truncated"],
        }
        return perceivo.primitives.AgentOutput(
            artifact=perceivo.primitives.Artifact(
                type=perceivo.primitives.ArtifactType.JSON,
                data=read_payload,
                mime_type="application/json",
            ),
            response_data=read_payload,
        )

    affected_rows = result["row_count"]
    # Past the row cap the count is a floor, not the total.
    capped = " (at least; the count was capped)" if result["truncated"] else ""
    write_payload = {
        "success": True,
        "operation": operation,
        "rows": [],
        "row_count": affected_rows,
        "columns": [],
        "truncated": result["truncated"],
        "affected_rows": affected_rows,
        "message": f"{affected_rows} rows affected{capped}",
    }
    return perceivo.primitives.AgentOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data=write_payload,
            mime_type="application/json",
        ),
        response_data=write_payload,
    )
